// Redact secrets before writing audit records. Drops key-like values.
const e = $input.first().json;
const REDACT = ['api_key','apikey','authorization','bearer','token','secret','password','app_id','cert_id'];
const clean = (v) => {
  if (Array.isArray(v)) return v.map(clean);
  if (v && typeof v === 'object') { const o = {}; for (const [k, val] of Object.entries(v)) { o[k] = REDACT.some((r) => k.toLowerCase().includes(r)) ? '[REDACTED]' : clean(val); } return o; }
  if (typeof v === 'string' && /^(tvly-|re_|Bearer |Basic )/i.test(v)) return '[REDACTED]';
  return v;
};
return [{ json: { operation: 'audit', payload: { procurement_id: e.procurement_id, trace_id: e.trace_id, agent_name: e.agent_name, event: e.event, source: e.source ?? null, source_url: e.source_url ?? null, retrieved_at: e.retrieved_at ?? null, detail: clean(e.detail ?? {}) } } }];
